@Component("notebook-handler")
@ProcessingGroup("notebook-processing-group")
public class NotebookEventHandler {
	
	// core constructor
	NotebookEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateNotebookEvent
     */
    @EventHandler
    public void handle( CreateNotebookEvent event) {
        entityManager.persist(new Notebook(event.getNotebookId(), event.getTitle(), event.getRepository(), event.getWorkspace(), event.getDatasets(), event.getExperiments(), event.getQueries(), event.getLanguage()));
    }

    /*
     * @param	event UpdateNotebookEvent
     */
    @EventHandler
    public Notebook handle( UpdateNotebookEvent event) {
    	entityManager.merge(new Notebook(event.getNotebookId(), event.getTitle(), event.getRepository(), event.getWorkspace(), event.getDatasets(), event.getExperiments(), event.getQueries(), event.getLanguage()));
    }
    
    /*
     * @param	event DeleteNotebookEvent
     */
    @EventHandler
    public void on( DeleteNotebookEvent event) {
    	Notebook entity = new Notebook();
   
    	// ------------------------------------------
    	// apply the NotebookId
    	// ------------------------------------------
    	entity.setNotebookId( event.getNotebookId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final NotebookRepository notebookEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(NotebookEventHandler.class.getName());

}
